class AgentState(MessagesState):
    tool_rounds: int

def agent_node(state: AgentState) -> dict:
    response = model_with_tools.invoke([SYSTEM_PROMPT, *state['messages']])
    rounds = state['tool_rounds'] + (1 if response.tool_calls else 0)
    return {'messages': [response], 'tool_rounds': rounds}

def route_after_agent(state: AgentState) -> Literal['tools', 'end']:
    last = state['messages'][-1]
    if last.tool_calls and state['tool_rounds'] < MAX_TOOL_ROUNDS:
        return 'tools'
    return 'end'

builder.add_conditional_edges('agent', route_after_agent, {'tools': 'tools', 'end': END})
builder.add_edge('tools', 'agent')
